"""Additive energy of a set, three equivalent ways."""
from __future__ import annotations
from collections import Counter
from typing import Dict, Sequence


def self_convolution(s: Sequence[int]) -> Dict[int, int]:
    """r_s(x) = #{(a,b) in s x s : a+b = x}."""
    c: Counter[int] = Counter()
    for a in s:
        for b in s:
            c[a + b] += 1
    return dict(c)


def additive_energy_convolution(s: Sequence[int]) -> int:
    """E[s] = sum_x r_s(x)^2  (squared L2 norm of the convolution kernel)."""
    return sum(r * r for r in self_convolution(s).values())


def additive_energy_bruteforce(s: Sequence[int]) -> int:
    """E[s] as a direct count of quadruples with a+b = c+d."""
    return sum(
        1 for a in s for b in s for c in s for d in s if a + b == c + d
    )


if __name__ == "__main__":
    for s in ([0, 1, 3, 7], [0, 1, 2, 3], [0, 1, 3, 7, 12]):
        conv = additive_energy_convolution(set(s))
        brute = additive_energy_bruteforce(set(s))
        print(s, "E =", conv, "(brute", brute, ")", "match", conv == brute)

"""Empirically confirm the universal energy floor E[s] >= 2n^2 - n."""
from __future__ import annotations
from collections import Counter
from itertools import combinations
from typing import Sequence


def additive_energy(s: Sequence[int]) -> int:
    c: Counter[int] = Counter()
    for a in s:
        for b in s:
            c[a + b] += 1
    return sum(r * r for r in c.values())


def energy_floor(n: int) -> int:
    return 2 * n * n - n


if __name__ == "__main__":
    N, n = 12, 4
    minimum = None
    violations = 0
    for combo in combinations(range(N), n):
        e = additive_energy(combo)
        if e < energy_floor(n):
            violations += 1
        if minimum is None or e < minimum[0]:
            minimum = (e, combo)
    print(f"scanned all {n}-subsets of {{0..{N-1}}}")
    print("floor 2n^2-n =", energy_floor(n))
    print("observed minimum:", minimum)
    print("floor violations:", violations, "(should be 0)")

"""The energy defect D(s) counts non-trivial additive coincidences exactly."""
from __future__ import annotations
from collections import Counter
from typing import List, Sequence, Tuple


def additive_energy(s: Sequence[int]) -> int:
    c: Counter[int] = Counter()
    for a in s:
        for b in s:
            c[a + b] += 1
    return sum(r * r for r in c.values())


def energy_defect(s: Sequence[int]) -> int:
    us = sorted(set(s))
    n = len(us)
    return additive_energy(us) - (2 * n * n - n)


def nontrivial_coincidences(s: Sequence[int]) -> List[Tuple[int, int, int, int]]:
    """Quadruples a+b=c+d with a != c and a != d (outside both kernels)."""
    us = sorted(set(s))
    return [
        (a, b, c, d)
        for a in us for b in us for c in us for d in us
        if a + b == c + d and a != c and a != d
    ]


if __name__ == "__main__":
    for s in ([0, 1, 3, 7], [0, 1, 2, 3], [0, 1, 2]):
        d = energy_defect(s)
        k = len(nontrivial_coincidences(s))
        print(s, "defect D =", d, " nontrivial coincidences =", k,
              " Sidon:", d == 0)

